SCIENCE={}
for row in ROWS.splitlines():
    code,*values=row.split("|")
    if len(values)!=len(KEYS) or any(not v.strip() for v in values):
        raise ValueError("Incomplete scientific overview: "+code)
    SCIENCE[code]=dict(zip(KEYS,values))
if set(SCIENCE)!=set(LOCALES):
    raise ValueError("Missing locale in science registry")

def method_for_route(route: str) -> str:
    low=str(route).lower()
    if any(token in low for token in ("time","timeline")):
        return SCIENCE[locale()]["timeline"]
    if "indice" in low or "index" in low:
        return SCIENCE[locale()]["indices"]
    if "eval" in low or "model" in low or "science" in low:
        return SCIENCE[locale()]["evaluation"] if "eval" in low else SCIENCE[locale()]["models"]
    if "detective" in low or "outlier" in low:
        return SCIENCE[locale()]["forensics"]
    if "inspector" in low:
        return SCIENCE[locale()]["inspector"]
    if "market" in low or "merchant" in low:
        return SCIENCE[locale()]["market"]
    return SCIENCE[locale()]["garage"]


def localized_science_intro(route: str):
    """Introduce any science route in the selected language, no fake data."""
    import streamlit as st
    from pricing.i18n import localized_panel
    from pricing.i18n_science_legal import copy
    if locale() in ("en-GB", "en-US"):
        return
    st.markdown("### "+localized_panel(route))
    st.markdown(method_for_route(route))
    st.caption(copy("science_limits"))
